wo=openpyxl.load_workbook(out, data_only=False)
wg=openpyxl.load_workbook(gld, data_only=False)

# check formatting (styles) preserved for every cell that existed in input
style_mismatches=[]
for sn in wi.sheetnames:
    si=wi[sn]; so=wo[sn]
    for row in si.iter_rows():
        for ci in row:
            co=so[ci.coordinate]
            for attr in ['style_id','number_format','fill','font','border','alignment','protection']:
                a=getattr(ci, attr)
                b=getattr(co, attr)
                # style_id is an internal id that can shift after save; compare other props
                if attr=='style_id':
                    continue
                def norm(v):
                    if v is None: return None
                    try:
                        return repr(v.__dict__) if hasattr(v,'__dict__') else repr(v)
                    except Exception:
                        return repr(v)
                if norm(a)!=norm(b):
                    style_mismatches.append((sn,ci.coordinate,attr,norm(a),norm(b)))
print('style mismatches (excluding style_id):', len(style_mismatches))
for m in style_mismatches[:10]: print(m)

# check number format codes explicitly
for sn in wi.sheetnames:
    si=wi[sn]; so=wo[sn]
    diffs=[]
    for row in si.iter_rows():
        for ci in row:
            co=so[ci.coordinate]
            if ci.number_format != co.number_format:
                diffs.append((ci.coordinate, ci.number_format, co.number_format))
    print(sn,'number_format diffs:',len(diffs), diffs[:10])

# confirm 311 filled and all match golden non-formula
filled=0
for sn in wi.sheetnames:
    si=wi[sn]; so=wo[sn]; sg=wg[sn]
    for row in si.iter_rows():
        for ci in row:
            if ci.value is None and so[ci.coordinate].value is not None and not (isinstance(so[ci.coordinate].value,str) and so[ci.coordinate].value.startswith('=')):
                filled+=1
